import * as THREE from './vendor/three.module.js';

const CITIES = [
  {id:'tunis',name:'Tunis',country:'Tunisia',flag:'🇹🇳',x:-.8,z:2.6,cost:0,color:0xf9a96e},
  {id:'paris',name:'Paris',country:'France',flag:'🇫🇷',x:-2.5,z:-2.15,cost:0,color:0x9bd6a1},
  {id:'rome',name:'Rome',country:'Italy',flag:'🇮🇹',x:1.35,z:.28,cost:0,color:0xf6c77c},
  {id:'barcelona',name:'Barcelona',country:'Spain',flag:'🇪🇸',x:-4.2,z:.35,cost:850,color:0xf5be84},
  {id:'berlin',name:'Berlin',country:'Germany',flag:'🇩🇪',x:2.15,z:-2.7,cost:1050,color:0xa2cbcb},
  {id:'istanbul',name:'Istanbul',country:'Türkiye',flag:'🇹🇷',x:5.25,z:.9,cost:1250,color:0xdab3c6},
  {id:'lisbon',name:'Lisbon',country:'Portugal',flag:'🇵🇹',x:-5.9,z:.95,cost:1450,color:0xc5d69d},
  {id:'amsterdam',name:'Amsterdam',country:'Netherlands',flag:'🇳🇱',x:-.3,z:-3.15,cost:1650,color:0xa9cee1}
];
const byId = Object.fromEntries(CITIES.map(c=>[c.id,c]));
const $ = id => document.getElementById(id);
const moneyText = n => '€' + Math.floor(n).toLocaleString('en-US');
const cap = 12;
const busCost = 950;
const storeKey = 'souha-bus-v1';
let sound = localStorage.getItem('souha-sound') !== 'off';
let selectedStation = 'tunis';
let selectedBus = 1;
let destination = 'paris';
let boardCount = 0;
let state;

function freshState(){return {version:1,money:790,moved:0,opened:['tunis','paris','rome'],queues:{tunis:{paris:7,rome:5},paris:{tunis:5,rome:3},rome:{tunis:6,paris:2}},buses:[{id:1,location:'tunis',status:'idle',passengers:0,destination:null,departure:0,arrival:0,origin:null,fare:0}],nextBusId:2,lastSpawn:Date.now()};}
function load(){try{const saved=JSON.parse(localStorage.getItem(storeKey));if(saved?.version===1&&Array.isArray(saved.buses)&&Array.isArray(saved.opened))return saved;}catch{}return freshState();}
function save(){localStorage.setItem(storeKey,JSON.stringify(state));}
state=load();
function fare(a,b){const x=byId[a],y=byId[b];return Math.round((43+Math.hypot(x.x-y.x,x.z-y.z)*8)/5)*5;}
function duration(a,b){const x=byId[a],y=byId[b];return Math.round(Math.max(18,Math.min(40,14+Math.hypot(x.x-y.x,x.z-y.z)*3.4)))*1000;}
function waiting(a,b){return state.queues[a]?.[b]||0;}
function stationWaiting(a){return Object.values(state.queues[a]||{}).reduce((n,v)=>n+v,0);}
function getBus(){return state.buses.find(b=>b.id===selectedBus);}
function beep(freq=660){if(!sound)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.045,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.18);osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.18);osc.onended=()=>ctx.close();}catch{}}
function toast(message,error=false){const box=document.createElement('div');box.className='toast'+(error?' error':'');box.textContent=message;$('toast-stack').appendChild(box);setTimeout(()=>box.remove(),3500);}

function availableBuses(){return state.buses.filter(b=>b.status==='idle'&&b.location===selectedStation);}
function syncSelection(){if(!state.opened.includes(selectedStation))selectedStation=state.opened[0];const options=availableBuses();if(!options.some(b=>b.id===selectedBus))selectedBus=options[0]?.id??null;const possible=state.opened.filter(x=>x!==selectedStation);const bus=getBus();if(bus?.passengers&&possible.includes(bus.destination))destination=bus.destination;else if(!possible.includes(destination))destination=possible[0];const max=bus?Math.min(waiting(selectedStation,destination),cap-bus.passengers):0;boardCount=Math.max(0,Math.min(boardCount||max,max));if(boardCount===0&&max>0)boardCount=max;}

function renderUI(){syncSelection();$('money').textContent=moneyText(state.money);$('moved').textContent=state.moved.toLocaleString();$('fleet-count').innerHTML=`${state.buses.length} <em>${state.buses.length===1?'bus':'buses'}</em>`;$('fleet-subcount').textContent=`${state.buses.length} ${state.buses.length===1?'bus':'buses'}`;$('station-count').innerHTML=`${state.opened.length} <em>countries</em>`;
  $('station-list').innerHTML=state.opened.map(id=>{const c=byId[id];return `<button class="station-item ${id===selectedStation?'selected':''}" data-station="${id}"><span class="flag">${c.flag}</span><span><span class="city">${c.name}</span><small>${c.country}</small></span><span class="queue-badge">${stationWaiting(id)}</span></button>`}).join('');
  const city=byId[selectedStation];$('selected-station').innerHTML=`<span class="selected-flag">${city.flag}</span><span><b>${city.name} Station</b><small>${city.country}</small></span><span class="selected-queue">${stationWaiting(selectedStation)} waiting</span>`;
  const buses=availableBuses();$('bus-select').innerHTML=buses.length?buses.map(b=>`<option value="${b.id}">🚌 Souha Bus #${String(b.id).padStart(2,'0')} · ${cap-b.passengers} seats free</option>`).join(''):'<option value="">No bus at this station</option>';$('bus-select').disabled=!buses.length;if(selectedBus)$('bus-select').value=String(selectedBus);
  const bus=getBus();$('bus-status').textContent=bus?.passengers?`${bus.passengers} boarded for ${byId[bus.destination].name} · ${cap-bus.passengers} seats left`:buses.length?'Ready to welcome travelers':'Select a station with an available bus';
  const possible=state.opened.filter(x=>x!==selectedStation);$('destination-select').innerHTML=possible.map(id=>`<option value="${id}">${byId[id].flag} ${byId[id].name}, ${byId[id].country}</option>`).join('');$('destination-select').value=destination||'';$('destination-select').disabled=!buses.length||!!bus?.passengers;
  const wait=waiting(selectedStation,destination);$('waiting-count').textContent=`${wait} ready`;$('route-fare').textContent=destination?`${moneyText(fare(selectedStation,destination))} per passenger · ${Math.round(duration(selectedStation,destination)/1000)}s journey`:'';$('board-count').textContent=boardCount;
  $('minus-count').disabled=boardCount<=1;$('plus-count').disabled=boardCount>=Math.min(wait,cap-(bus?.passengers||0));$('board-button').disabled=!bus||wait===0||boardCount===0||!!bus.passengers&&bus.destination!==destination;$('depart-button').disabled=!bus||bus.passengers===0;
  $('trip-note').textContent=!bus?'Send a bus here by choosing this station as a destination.':bus.passengers?`${bus.passengers} traveler${bus.passengers===1?'':'s'} on board · Earn ${moneyText(bus.passengers*fare(selectedStation,bus.destination))} on arrival`:wait===0?'No travelers for this route yet. New travelers arrive often.':'Board travelers, then start the trip.';
  $('fleet-list').innerHTML=state.buses.map(b=>{const travelling=b.status==='trip',place=travelling?`${byId[b.origin].name} → ${byId[b.destination].name}`:`At ${byId[b.location].name}`,timeLeft=travelling?` · ${Math.max(0,Math.ceil((b.arrival-Date.now())/1000))}s left`:'';return `<div class="fleet-item ${b.id===selectedBus?'selected':''}" data-bus="${b.id}"><span class="fleet-bus-icon">▰</span><span><b>Souha Bus #${String(b.id).padStart(2,'0')}</b><small>${place}${timeLeft}${!travelling&&b.passengers?` · ${b.passengers} aboard`:''}</small></span><span class="fleet-status ${travelling?'trip':''}">${travelling?'ON TRIP':'READY'}</span></div>`}).join('');$('buy-bus').disabled=state.money<busCost;
  renderLabels();updateBuses();
}

function selectStation(id){if(!state.opened.includes(id)){openBuild();return;}selectedStation=id;destination=state.opened.find(x=>x!==id);selectedBus=availableBuses()[0]?.id??null;boardCount=0;renderUI();beep(540);}
function board(){const bus=getBus();if(!bus||bus.status!=='idle'||bus.location!==selectedStation||boardCount<1)return;const n=Math.min(boardCount,waiting(selectedStation,destination),cap-bus.passengers);if(!n)return;state.queues[selectedStation][destination]-=n;bus.passengers+=n;bus.destination=destination;save();renderUI();toast(`${n} traveler${n===1?'':'s'} boarded for ${byId[destination].name}!`);beep(730);}
function depart(){const bus=getBus();if(!bus||bus.status!=='idle'||bus.passengers<1)return;bus.origin=bus.location;bus.fare=fare(bus.origin,bus.destination);bus.departure=Date.now();bus.arrival=bus.departure+duration(bus.origin,bus.destination);bus.status='trip';save();renderUI();toast(`Souha Bus #${String(bus.id).padStart(2,'0')} is off to ${byId[bus.destination].name}!`);beep(840);}
function finishTrips(){let changed=false;for(const bus of state.buses){if(bus.status==='trip'&&Date.now()>=bus.arrival){const earned=bus.passengers*bus.fare;state.money+=earned;state.moved+=bus.passengers;bus.location=bus.destination;bus.status='idle';bus.passengers=0;bus.destination=null;bus.origin=null;bus.departure=0;bus.arrival=0;bus.fare=0;changed=true;toast(`Bus #${String(bus.id).padStart(2,'0')} arrived! ${moneyText(earned)} earned.`);beep(940);}}if(changed){save();renderUI();}}
function spawnTravelers(){const now=Date.now();if(now-state.lastSpawn<7000)return;const turns=Math.min(18,Math.floor((now-state.lastSpawn)/7000));for(let i=0;i<turns;i++){const origin=state.opened[Math.floor(Math.random()*state.opened.length)],destinations=state.opened.filter(x=>x!==origin),dest=destinations[Math.floor(Math.random()*destinations.length)];state.queues[origin]??={};state.queues[origin][dest]=Math.min(36,(state.queues[origin][dest]||0)+1+Math.floor(Math.random()*3));}state.lastSpawn=now;save();renderUI();}
function buyBus(){if(state.money<busCost)return toast(`You need ${moneyText(busCost-state.money)} more for a bus.`,true);state.money-=busCost;const id=state.nextBusId++;state.buses.push({id,location:selectedStation,status:'idle',passengers:0,destination:null,departure:0,arrival:0,origin:null,fare:0});selectedBus=id;save();renderUI();toast(`New orange Souha Bus #${String(id).padStart(2,'0')} joined your fleet!`);beep(880);}
function openBuild(){$('build-modal').classList.remove('hidden');renderBuild();}
function renderBuild(){const pending=CITIES.filter(c=>!state.opened.includes(c.id));$('available-stations').innerHTML=pending.length?pending.map(c=>`<div class="available-card"><div class="new-flag">${c.flag}</div><b>${c.name}</b><small>${c.country} · New travelers await</small><button data-build="${c.id}" ${state.money<c.cost?'disabled':''}>Build station · ${moneyText(c.cost)}</button></div>`).join(''):'<p>Every station is open. Your network spans the whole map!</p>';}
function buildStation(id){const c=byId[id];if(!c||state.opened.includes(id))return;if(state.money<c.cost)return toast(`You need ${moneyText(c.cost-state.money)} more for ${c.name}.`,true);state.money-=c.cost;state.opened.push(id);state.queues[id]={};for(const origin of state.opened){if(origin===id)continue;state.queues[id][origin]=2+Math.floor(Math.random()*4);state.queues[origin]??={};state.queues[origin][id]=1+Math.floor(Math.random()*3);}selectedStation=id;selectedBus=null;destination=state.opened[0];$('build-modal').classList.add('hidden');save();rebuildRoutes();renderUI();toast(`${c.name} Station is open! Travelers are already waiting.`);beep(960);}

// Three.js miniature world
const scene=new THREE.Scene();scene.background=new THREE.Color(0xc2e1e7);scene.fog=new THREE.Fog(0xc2e1e7,20,38);
const wrap=$('scene-wrap'),canvas=$('game-canvas');const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;
const camera=new THREE.OrthographicCamera(-8.5,8.5,5.7,-5.7,.1,100);let angle=.04,zoom=1;function positionCamera(){const r=17;camera.position.set(Math.sin(angle)*r,15,Math.cos(angle)*r);camera.lookAt(0,0,0);camera.zoom=zoom;camera.updateProjectionMatrix();}positionCamera();
scene.add(new THREE.HemisphereLight(0xffffff,0xb7d3c1,1.8));const sun=new THREE.DirectionalLight(0xfff4d7,2);sun.position.set(-5,12,6);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-12;sun.shadow.camera.right=12;sun.shadow.camera.top=12;sun.shadow.camera.bottom=-12;sun.shadow.normalBias=.025;scene.add(sun);
const mat=(color,other={})=>new THREE.MeshLambertMaterial({color,flatShading:true,...other});const green=mat(0xa8d9a6),grass=mat(0xb7dcaa),darkGreen=mat(0x80b88b),ocean=mat(0xa6d3df),white=mat(0xfffaf0),roadMat=mat(0xf2e8d0),orange=mat(0xf28a47),roof=mat(0xeab675),trunk=mat(0x9a7b55),stone=mat(0xe6dfc3),shadowGreen=mat(0x8ec89a);
function mesh(geo,material,parent=scene,x=0,y=0,z=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.receiveShadow=true;m.castShadow=true;parent.add(m);return m;}
const water=mesh(new THREE.PlaneGeometry(200,200),ocean);water.rotation.x=-Math.PI/2;water.position.y=-.45;water.receiveShadow=false;
const island=mesh(new THREE.BoxGeometry(14.4,.48,9.2),green,scene,0,-.18,0);island.castShadow=false;
for(const [x,z,sx,sz,c] of [[-5.4,-2.8,1.7,1.1,0xb6dea9],[4.3,-2.3,1.9,1.2,0xc2e1ae],[-4.7,2.3,2.1,1.1,0xb2dda2],[2.7,2.7,2.7,1.2,0xb8deaa]]){const patch=mesh(new THREE.CylinderGeometry(1,1,.018,7),mat(c),scene,x,.07,z);patch.scale.set(sx,1,sz);}
function tree(x,z,s=1){mesh(new THREE.CylinderGeometry(.055*s,.09*s,.32*s,5),trunk,scene,x,.25*s,z);const top=mesh(new THREE.IcosahedronGeometry(.28*s,0),Math.random()>.5?darkGreen:shadowGreen,scene,x,.52*s,z);top.rotation.y=Math.random()*Math.PI;}
for(let i=0;i<75;i++){const x=-6.8+Math.random()*13.6,z=-4.25+Math.random()*8.5;if(CITIES.some(c=>Math.hypot(c.x-x,c.z-z)<.9))continue;if(Math.random()>.27)tree(x,z,.55+Math.random()*.55);else{const tuft=mesh(new THREE.ConeGeometry(.1,.16,4),darkGreen,scene,x,.12,z);tuft.rotation.y=Math.random()*6;}}
for(let i=0;i<22;i++){const x=-7+Math.random()*14,z=-4.45+Math.random()*8.9;if(CITIES.some(c=>Math.hypot(c.x-x,c.z-z)<.7))continue;const flower=mesh(new THREE.IcosahedronGeometry(.055,0),mat(i%3?0xffe6ae:0xffbca9),scene,x,.12,z);flower.castShadow=false;}
const stationGroups={};const routeGroup=new THREE.Group();scene.add(routeGroup);const busGroups={};
function person(parent,x,z,color){mesh(new THREE.CylinderGeometry(.07,.09,.23,6),mat(color),parent,x,.18,z);mesh(new THREE.IcosahedronGeometry(.09,0),mat(0xf4c9a4),parent,x,.39,z);}
function makeStation(c){const g=new THREE.Group();g.position.set(c.x,0,c.z);scene.add(g);const active=state.opened.includes(c.id);stationGroups[c.id]=g;const pad=mesh(new THREE.CylinderGeometry(.68,.76,.09,8),active?stone:mat(0xc9d4c6),g,0,.08,0);pad.castShadow=false;const ring=mesh(new THREE.TorusGeometry(.71,.025,5,32),active?orange:mat(0xd5ded2),g,0,.145,0);ring.rotation.x=Math.PI/2;ring.castShadow=false;
  if(active){const building=mesh(new THREE.BoxGeometry(.68,.48,.42),white,g,-.16,.4,-.11);mesh(new THREE.ConeGeometry(.51,.27,4),mat(c.color),g,-.16,.77,-.11).rotation.y=Math.PI/4;mesh(new THREE.BoxGeometry(.18,.25,.015),mat(0x78b3aa),g,-.18,.34,.106);mesh(new THREE.BoxGeometry(.35,.05,.22),roof,g,.34,.48,.22);for(let i=0;i<3;i++)person(g,.18+i*.13,.49,i%2?0x78aa99:0xf5a775);}
  else{mesh(new THREE.BoxGeometry(.5,.25,.38),mat(0xe6ede1),g,0,.26,0);mesh(new THREE.ConeGeometry(.35,.2,4),mat(0xd4dfd1),g,0,.5,0).rotation.y=Math.PI/4;}
  const pin=mesh(new THREE.CylinderGeometry(.075,.11,.35,6),active?orange:mat(0xbecbbf),g,.49,.38,-.38);pin.castShadow=false;mesh(new THREE.IcosahedronGeometry(.2,1),active?orange:mat(0xbecbbf),g,.49,.67,-.38);
}
function rebuildStations(){Object.values(stationGroups).forEach(g=>scene.remove(g));for(const key of Object.keys(stationGroups))delete stationGroups[key];CITIES.forEach(makeStation);}
function curveBetween(a,b,y=.15){const aa=byId[a],bb=byId[b],mid=new THREE.Vector3((aa.x+bb.x)/2,y,(aa.z+bb.z)/2);mid.x+=(bb.z-aa.z)*.08;mid.z-=(bb.x-aa.x)*.08;return new THREE.CatmullRomCurve3([new THREE.Vector3(aa.x,y,aa.z),mid,new THREE.Vector3(bb.x,y,bb.z)]);}
function rebuildRoutes(){while(routeGroup.children.length){const obj=routeGroup.children[0];routeGroup.remove(obj);obj.geometry?.dispose();}rebuildStations();const open=state.opened;for(let i=0;i<open.length;i++){const source=open[i],others=open.filter(x=>x!==source).sort((a,b)=>Math.hypot(byId[source].x-byId[a].x,byId[source].z-byId[a].z)-Math.hypot(byId[source].x-byId[b].x,byId[source].z-byId[b].z)).slice(0,2);for(const target of others){if(open.indexOf(target)<i)continue;const curve=curveBetween(source,target,.135);const road=mesh(new THREE.TubeGeometry(curve,24,.06,5,false),roadMat,routeGroup);road.castShadow=false;const line=mesh(new THREE.TubeGeometry(curve,24,.012,4,false),mat(0xffffff),routeGroup);line.position.y=.02;line.castShadow=false;}}}
function brandTexture(){const cnv=document.createElement('canvas');cnv.width=512;cnv.height=128;const ctx=cnv.getContext('2d');ctx.fillStyle='#fff7eb';ctx.fillRect(0,0,512,128);ctx.fillStyle='#bb5225';ctx.font='bold 67px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('Souha Bus',256,70);const t=new THREE.CanvasTexture(cnv);t.colorSpace=THREE.SRGBColorSpace;return t;}const busBrand=brandTexture();
function makeBus(b){const g=new THREE.Group();scene.add(g);busGroups[b.id]=g;const body=mesh(new THREE.BoxGeometry(1.35,.43,.56),orange,g,0,.44,0);mesh(new THREE.BoxGeometry(.42,.43,.56),orange,g,.83,.44,0);mesh(new THREE.BoxGeometry(1.22,.22,.57),mat(0x78abb1),g,-.05,.7,0);mesh(new THREE.BoxGeometry(.34,.27,.57),mat(0x83bac0),g,.75,.67,0);mesh(new THREE.BoxGeometry(1.9,.045,.59),mat(0xfbb375),g,.05,.87,0);for(const side of [-1,1]){for(const x of [-.48,.47]){const wheel=mesh(new THREE.CylinderGeometry(.17,.17,.08,10),mat(0x34424a),g,x,.2,side*.33);wheel.rotation.x=Math.PI/2;mesh(new THREE.CylinderGeometry(.07,.07,.084,10),mat(0xe6d9c4),g,x,.2,side*.33).rotation.x=Math.PI/2;}const sign=mesh(new THREE.PlaneGeometry(.92,.23),new THREE.MeshBasicMaterial({map:busBrand,side:THREE.DoubleSide}),g,-.12,.49,side*.287);if(side<0)sign.rotation.y=Math.PI;sign.castShadow=false;}mesh(new THREE.BoxGeometry(.04,.12,.48),mat(0xfff1b4),g,1.055,.5,0);return g;}
function updateBuses(){for(const b of state.buses){if(!busGroups[b.id])makeBus(b);const g=busGroups[b.id];if(b.status==='trip'){const progress=THREE.MathUtils.clamp((Date.now()-b.departure)/(b.arrival-b.departure),0,1);const curve=curveBetween(b.origin,b.destination,.22);const p=curve.getPoint(progress),t=curve.getTangent(progress);g.position.set(p.x,.08+Math.sin(performance.now()*.008)*.012,p.z);g.rotation.y=-Math.atan2(t.z,t.x);}else{const c=byId[b.location],siblings=state.buses.filter(x=>x.status==='idle'&&x.location===b.location),index=siblings.findIndex(x=>x.id===b.id);g.position.set(c.x-.83+(index%3)*.22,.08,c.z+.74+Math.floor(index/3)*.3);g.rotation.y=0;}}}
function renderLabels(){const host=$('map-labels');host.innerHTML=CITIES.map(c=>`<button class="station-label ${state.opened.includes(c.id)?'':'locked'} ${selectedStation===c.id?'selected':''}" data-label="${c.id}">${c.flag} ${c.name}${state.opened.includes(c.id)?'':' ＋'}</button>`).join('');positionLabels();}
function positionLabels(){const r=wrap.getBoundingClientRect();for(const c of CITIES){const el=wrap.querySelector(`[data-label="${c.id}"]`);if(!el)continue;const v=new THREE.Vector3(c.x,.95,c.z).project(camera),half=el.offsetWidth/2;const px=THREE.MathUtils.clamp((v.x*.5+.5)*r.width,half+5,r.width-half-5),py=THREE.MathUtils.clamp((-v.y*.5+.5)*r.height,el.offsetHeight+6,r.height-6);el.style.left=`${px}px`;el.style.top=`${py}px`;el.style.display=v.z>1?'none':'';}}
function resize(){const w=wrap.clientWidth,h=wrap.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);const aspect=w/h,halfX=Math.max(7.9,6.05*aspect);camera.left=-halfX;camera.right=halfX;camera.top=halfX/aspect;camera.bottom=-halfX/aspect;camera.updateProjectionMatrix();positionLabels();}new ResizeObserver(resize).observe(wrap);
let dragging=false,dragX=0,hasDragged=false;canvas.addEventListener('pointerdown',e=>{dragging=true;dragX=e.clientX;hasDragged=false;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragging)return;const d=e.clientX-dragX;if(Math.abs(d)>2)hasDragged=true;angle+=d*.006;angle=Math.max(-.8,Math.min(.8,angle));dragX=e.clientX;positionCamera();positionLabels();});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=THREE.MathUtils.clamp(zoom+(e.deltaY<0?.08:-.08),.83,1.65);positionCamera();positionLabels();},{passive:false});
function animate(){requestAnimationFrame(animate);updateBuses();positionLabels();renderer.render(scene,camera);}rebuildRoutes();resize();animate();

$('station-list').addEventListener('click',e=>{const b=e.target.closest('[data-station]');if(b)selectStation(b.dataset.station)});$('map-labels').addEventListener('click',e=>{const b=e.target.closest('[data-label]');if(b)selectStation(b.dataset.label)});$('fleet-list').addEventListener('click',e=>{const row=e.target.closest('[data-bus]');if(!row)return;const bus=state.buses.find(b=>b.id===Number(row.dataset.bus));if(bus.status==='trip')return toast(`Bus #${String(bus.id).padStart(2,'0')} is traveling to ${byId[bus.destination].name}.`);selectedStation=bus.location;selectedBus=bus.id;destination=bus.destination||state.opened.find(x=>x!==selectedStation);boardCount=0;renderUI()});$('bus-select').addEventListener('change',e=>{selectedBus=Number(e.target.value);const b=getBus();if(b?.passengers)destination=b.destination;boardCount=0;renderUI()});$('destination-select').addEventListener('change',e=>{destination=e.target.value;boardCount=0;renderUI()});$('minus-count').addEventListener('click',()=>{boardCount=Math.max(1,boardCount-1);renderUI()});$('plus-count').addEventListener('click',()=>{boardCount++;renderUI()});$('board-button').addEventListener('click',board);$('depart-button').addEventListener('click',depart);$('buy-bus').addEventListener('click',buyBus);$('open-build').addEventListener('click',openBuild);$('map-build').addEventListener('click',openBuild);$('close-modal').addEventListener('click',()=>$('build-modal').classList.add('hidden'));$('build-modal').addEventListener('click',e=>{if(e.target.id==='build-modal')$('build-modal').classList.add('hidden');const b=e.target.closest('[data-build]');if(b)buildStation(b.dataset.build)});window.addEventListener('keydown',e=>{if(e.key==='Escape')$('build-modal').classList.add('hidden')});$('sound-toggle').addEventListener('click',()=>{sound=!sound;localStorage.setItem('souha-sound',sound?'on':'off');$('sound-toggle').textContent=sound?'♪':'♩';toast(sound?'Sound on':'Sound off')});$('reset-button').addEventListener('click',()=>{if(!confirm('Start a new Souha Bus network? Your current progress will be erased.'))return;state=freshState();selectedStation='tunis';selectedBus=1;destination='paris';boardCount=0;save();rebuildRoutes();renderUI();toast('A fresh journey begins!')});
finishTrips();renderUI();setInterval(()=>{finishTrips();spawnTravelers();if(state.buses.some(b=>b.status==='trip'))renderUI()},1000);
